using System;
using System.IO;
using Microsoft.Build.Logging.StructuredLogger;
using System.Linq;
using System.Collections.Generic;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT ===");
Console.WriteLine($"Succeeded: {build.Succeeded}");
Console.WriteLine();

// Collect all errors
var errors = new List<(string project, string code, string file, int line, string message)>();
var warnings = new List<(string project, string code, string file, int line, string message)>();

build.VisitAllChildren<Error>(e => {
    string proj = "";
    var parent = e.Parent;
    while (parent != null) {
        if (parent is Project p) { proj = p.Name; break; }
        parent = (parent as TreeNode)?.Parent as BaseNode;
    }
    errors.Add((proj, e.Code ?? "", e.File ?? "", e.LineNumber, e.Text ?? e.ToString()));
});

build.VisitAllChildren<Warning>(w => {
    string proj = "";
    var parent = w.Parent;
    while (parent != null) {
        if (parent is Project p) { proj = p.Name; break; }
        parent = (parent as TreeNode)?.Parent as BaseNode;
    }
    warnings.Add((proj, w.Code ?? "", w.File ?? "", w.LineNumber, w.Text ?? w.ToString()));
});

Console.WriteLine($"=== ERRORS ({errors.Count}) ===");
foreach (var g in errors.GroupBy(e => e.project))
{
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var e in g)
    {
        Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
    }
}

Console.WriteLine($"\n=== WARNINGS ({warnings.Count}) ===");
foreach (var g in warnings.GroupBy(w => w.project))
{
    Console.WriteLine($"\n--- Project: {g.Key} ---");
    foreach (var w in g)
    {
        Console.WriteLine($"  [{w.code}] {w.file}({w.line}): {w.message}");
    }
}

// Show project dependency structure
Console.WriteLine("\n=== PROJECT STRUCTURE ===");
build.VisitAllChildren<Project>(p => {
    Console.WriteLine($"Project: {p.Name} | Succeeded: {p.Succeeded}");
});
